public class Solution {
    public bool IsCousins(TreeNode root, int x, int y) {
        var q = new System.Collections.Generic.Queue<(TreeNode node, TreeNode parent, int depth)>();
        q.Enqueue((root, null, 0));
        TreeNode px = null, py = null;
        int dx = -1, dy = -1;
