            if (n.val == x) { px = p; dx = d; }
            if (n.val == y) { py = p; dy = d; }
            if (n.left != null) q.Enqueue((n.left, n, d + 1));
            if (n.right != null) q.Enqueue((n.right, n, d + 1));
        }
        return dx == dy && px != py;
    }
}
```

