Two strings are close exactly when three conditions hold:

1. They have the same length.
2. They use the same set of distinct characters.
3. The sorted lists of character frequencies are identical.

The approach is to count the 26 letter frequencies for each word, then check that each letter appears in both words or in neither. Then sort both count arrays and compare them element by element.

```csharp
using System;

public class Solution {
    public bool CloseStrings(string word1, string word2) {
        if (word1.Length != word2.Length) return false;
        int[] a = new int[26];
        int[] b = new int[26];
        foreach (char c in word1) a[c - 'a']++;
        foreach (char c in word2) b[c - 'a']++;
        for (int i = 0; i < 26; i++) {
            if ((a[i] == 0) != (b[i] == 0)) return false;
        }
        Array.Sort(a);
        Array.Sort(b);
        for (int i = 0; i < 26; i++) {
            if (a[i] != b[i]) return false;
        }
        return true;
    }
}
```

