Build a dictionary from `knowledge`, then scan `s` once. Outside brackets, copy characters to a `StringBuilder`. On `(`, find the matching `)`, look up the key in between, and append its value or `?` if the key is unknown. The trailing spaces shown in the examples are formatting artifacts, so I ignore them. The scan is O(n) plus dictionary building.

```csharp
using System.Collections.Generic;
using System.Text;

public class Solution {
    public string Evaluate(string s, IList<IList<string>> knowledge) {
        var dict = new Dictionary<string, string>();
        foreach (var k in knowledge) {
            dict[k[0]] = k[1];
        }
        var sb = new StringBuilder();
        int i = 0;
        int n = s.Length;
        while (i < n) {
            if (s[i] == '(') {
                int j = i + 1;
                while (s[j] != ')') j++;
                string key = s.Substring(i + 1, j - i - 1);
                if (dict.TryGetValue(key, out var v)) sb.Append(v);
                else sb.Append('?');
                i = j + 1;
            } else {
                sb.Append(s[i]);
                i++;
            }
        }
        return sb.ToString();
    }
}
```

