```csharp
using System.Collections.Generic;

public class Solution {
    public IList<int> FindKDistantIndices(int[] nums, int key, int k) {
        var res = new List<int>();
        int n = nums.Length;
        for (int i = 0; i < n; i++) {
            int lo = System.Math.Max(0, i - k);
            int hi = System.Math.Min(n - 1, i + k);
            for (int j = lo; j <= hi; j++) {
                if (nums[j] == key) {
                    res.Add(i);
                    break;
                }
            }
        }
        return res;
    }
}
