Use prefix sums for rows and columns, and brute-force each top-left corner and size k, from the largest size down.

Sums can reach 50 · 10^6 = 5·10^7, which fits in an int, but I use long anyway.

Setup:
- rowP[i][j+1] is the sum of row i over columns 0..j.
- colP[i+1][j] is the sum of column j over rows 0..i.
- For each k from min(m,n) down to 2, and each top-left (i,j) with i+k<=m and j+k<=n:
  - Take the target as the sum of the first row, rowP[i][j+k] - rowP[i][j].
  - Check that every row i..i+k-1 has this sum.
  - Check that every column j..j+k-1 has this sum.
  - Compute both diagonals by direct loop, which costs O(k).
- If all checks pass, return k. If none pass, return 1.

The total cost is about 50·50·50·50 = 6M operations, which is fine.

```csharp
public class Solution {
    public int LargestMagicSquare(int[][] grid) {
        int m = grid.Length, n = grid[0].Length;
        long[,] rowP = new long[m, n + 1];
        long[,] colP = new long[m + 1, n];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                rowP[i, j + 1] = rowP[i, j] + grid[i][j];
                colP[i + 1, j] = colP[i, j] + grid[i][j];
            }
        for (int k = Math.Min(m, n); k >= 2; k--) {
            for (int i = 0; i + k <= m; i++) {
                for (int j = 0; j + k <= n; j++) {
                    long t = rowP[i, j + k] - rowP[i, j];
                    bool ok = true;
                    for (int r = i; r < i + k && ok; r++) {
                        if (rowP[r, j + k] - rowP[r, j] != t) ok = false;
                    }
                    for (int c = j; c < j + k && ok; c++) {
                        if (colP[i + k, c] - colP[i, c] != t) ok = false;
                    }
                    if (!ok) continue;
                    long d1 = 0, d2 = 0;
                    for (int d = 0; d < k; d++) {
                        d1 += grid[i + d][j + d];
                        d2 += grid[i + d][j + k - 1 - d];
                    }
                    if (d1 == t && d2 == t) return k;
                }
            }
        }
        return 1;
    }
}
```

