Use a level-order BFS: the first leaf reached is the nearest one, so its level is the minimum depth. BFS also avoids the deep recursion a skewed tree with up to 10^5 nodes would cause. An empty tree returns 0.

```csharp
public class Solution {
    public int MinDepth(TreeNode root) {
        if (root == null) return 0;
        var q = new System.Collections.Generic.Queue<TreeNode>();
        q.Enqueue(root);
        int depth = 1;
        while (q.Count > 0) {
            int n = q.Count;
            for (int i = 0; i < n; i++) {
                var node = q.Dequeue();
                if (node.left == null && node.right == null) return depth;
                if (node.left != null) q.Enqueue(node.left);
                if (node.right != null) q.Enqueue(node.right);
            }
            depth++;
        }
        return depth;
    }
}
```

