Since m ≤ 8, a bitmask DP over mentors works. Precompute the score for every student-mentor pair. Let `dp[mask]` be the best total when the students `0..popcount(mask)-1` have been assigned to the mentors in `mask`. For each mask, the next student is `i = popcount(mask)`, and we try every mentor `j` not in the mask:

`dp[mask | 1<<j] = max(dp[mask | 1<<j], dp[mask] + score[i][j])`

Initialize `dp` to -1 for unreachable states, with `dp[0] = 0`. The answer is `dp[(1<<m) - 1]`.

```csharp
public class Solution {
    public int MaxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.Length;
        int n = students[0].Length;
        int[,] score = new int[m, m];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < m; j++)
            {
                int s = 0;
                for (int k = 0; k < n; k++)
                    if (students[i][k] == mentors[j][k]) s++;
                score[i, j] = s;
            }
        int full = 1 << m;
        int[] dp = new int[full];
        for (int i = 0; i < full; i++) dp[i] = -1;
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++)
        {
            if (dp[mask] < 0) continue;
            int i = 0;
            int t = mask;
            while (t > 0) { i += t & 1; t >>= 1; }
            if (i >= m) continue;
            for (int j = 0; j < m; j++)
            {
                if ((mask & (1 << j)) != 0) continue;
                int nm = mask | (1 << j);
                int v = dp[mask] + score[i, j];
                if (v > dp[nm]) dp[nm] = v;
            }
        }
        return dp[full - 1];
    }
}
```

