2. Walk through the target positions `j` not yet in the mask. If the sticker still has a letter `target[j]`, use it and set bit `j` in the new mask.
3. Update `dp[newmask] = min(dp[newmask], dp[mask] + 1)`.

Because the new mask always includes bit `i`, it is strictly larger than the old one, so processing masks in increasing order is valid.

The answer is `dp[full]`, or `-1` if it is unreachable. The `-1` case is handled naturally, because if no sticker contains the needed letter the full mask is never reached.

The cost is 2^15 masks × 50 stickers × 15 positions, about 25M operations, which is fine.

The examples contain trailing spaces in the words, but the constraints say lowercase letters only. The code assumes `'a'..'z'` and skips any other character, so a space in a sticker is simply ignored. If the target contained a space, it would need a count slot, so I use a 128-size count array to be safe.

```csharp
public class Solution {
    public int MinStickers(string[] stickers, string target) {
        int n = target.Length;
        int full = (1 << n) - 1;
        int[][] cnt = new int[stickers.Length][];
        for (int s = 0; s < stickers.Length; s++) {
            cnt[s] = new int[128];
            foreach (char c in stickers[s]) cnt[s][c]++;
        }
        int INF = int.MaxValue / 2;
        int[] dp = new int[full + 1];
        for (int i = 0; i <= full; i++) dp[i] = INF;
        dp[0] = 0;
        int[] tmp = new int[128];
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] >= INF) continue;
            int i = 0;
            while (((mask >> i) & 1) == 1) i++;
            char need = target[i];
            for (int s = 0; s < stickers.Length; s++) {
                if (cnt[s][need] == 0) continue;
                System.Array.Copy(cnt[s], tmp, 128);
                int nm = mask;
                for (int j = 0; j < n; j++) {
                    if (((nm >> j) & 1) == 0 && tmp[target[j]] > 0) {
                        tmp[target[j]]--;
                        nm |= 1 << j;
                    }
                }
                if (dp[mask] + 1 < dp[nm]) dp[nm] = dp[mask] + 1;
            }
        }
        return dp[full] >= INF ? -1 : dp[full];
    }
}
