Iterate through the keypresses, computing each duration as `releaseTimes[i]` minus the previous release time (or just `releaseTimes[0]` for the first key). Keep the best duration and its key. Replace them when a duration is strictly longer, or when it ties the best and the key is lexicographically larger.

```csharp
public class Solution {
    public char SlowestKey(int[] releaseTimes, string keysPressed) {
        int best = releaseTimes[0];
        char key = keysPressed[0];
        for (int i = 1; i < releaseTimes.Length; i++) {
            int d = releaseTimes[i] - releaseTimes[i - 1];
            if (d > best || (d == best && keysPressed[i] > key)) {
                best = d;
                key = keysPressed[i];
            }
        }
        return key;
    }
}
