Sort by a combined key: the bit count first, then the value. Since values are at most 10^4, the key `bitCount * 100000 + value` captures both and sorts correctly in one pass.

```csharp
using System;

public class Solution {
    public int[] SortByBits(int[] arr) {
        int[] keys = new int[arr.Length];
        for (int i = 0; i < arr.Length; i++) {
            int v = arr[i];
            int c = 0;
            int t = v;
            while (t > 0) {
                c += t & 1;
                t >>= 1;
            }
            keys[i] = c * 100000 + v;
        }
        Array.Sort(keys);
        for (int i = 0; i < keys.Length; i++) {
            arr[i] = keys[i] % 100000;
        }
        return arr;
    }
}
```

