public class Solution {
    int[,,] mn = new int[30, 30, 30];
    int[,,] mx = new int[30, 30, 30];
    bool[,,] seen = new bool[30, 30, 30];

    void Go(int n, int a, int b) {
        if (seen[n, a, b]) return;
        seen[n, a, b] = true;
        if (a + b == n + 1) {
            mn[n, a, b] = 1;
            mx[n, a, b] = 1;
            return;
        }
        int half = n / 2;
        int best = int.MaxValue, worst = int.MinValue;
        int full = 1 << half;
        bool[] adv = new bool[n + 2];
        for (int mask = 0; mask < full; mask++) {
            bool ok = true;
            Array.Clear(adv, 0, adv.Length);
            for (int i = 1; i <= half; i++) {
                int j = n + 1 - i;
                bool bit = ((mask >> (i - 1)) & 1) == 1;
                if (i == a || i == b) {
                    if (bit) { ok = false; break; }
                    adv[i] = true;
                } else if (j == a || j == b) {
                    if (bit) { ok = false; break; }
                    adv[j] = true;
                } else {
                    if (bit) adv[j] = true; else adv[i] = true;
                }
            }
            if (!ok) continue;
            if (n % 2 == 1) adv[half + 1] = true;
            int cnt = 0, na = 0, nb = 0;
            for (int p = 1; p <= n; p++) {
                if (adv[p]) {
                    cnt++;
                    if (p == a) na = cnt;
                    if (p == b) nb = cnt;
                }
