            int lo = mn[cnt, na, nb] + 1;
            int hi = mx[cnt, na, nb] + 1;
            if (lo < best) best = lo;
            if (hi > worst) worst = hi;
        }
        mn[n, a, b] = best;
        mx[n, a, b] = worst;
    }

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        Go(n, firstPlayer, secondPlayer);
        return new int[] { mn[n, firstPlayer, secondPlayer], mx[n, firstPlayer, secondPlayer] };
    }
}
