Approach: compute the in-degree of every node. A valid tree has exactly one root (in-degree 0), and every other node has in-degree exactly 1. Then run a traversal from the root and check that all n nodes are visited.

1. Count in-degrees from both child arrays. If any node gets in-degree greater than 1, return false.
2. Find nodes with in-degree 0. There must be exactly one; otherwise return false.
3. Traverse from the root with a stack and a visited array. Because every in-degree is at most 1, no node is pushed twice unless there is a cycle, and a cycle cannot be reachable from the root without giving some node in-degree 2. The visited check is kept as a safeguard anyway.
4. Return true only if the visited count equals n.

Example 3: both nodes have in-degree 1, so there is no root and the answer is false.

```csharp
public class Solution {
    public bool ValidateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) {
                if (++indeg[leftChild[i]] > 1) return false;
            }
            if (rightChild[i] != -1) {
                if (++indeg[rightChild[i]] > 1) return false;
            }
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;
        bool[] visited = new bool[n];
        var stack = new System.Collections.Generic.Stack<int>();
        stack.Push(root);
        visited[root] = true;
        int count = 0;
        while (stack.Count > 0) {
            int u = stack.Pop();
            count++;
            int[] ch = new int[] { leftChild[u], rightChild[u] };
            foreach (int c in ch) {
                if (c != -1) {
                    if (visited[c]) return false;
                    visited[c] = true;
                    stack.Push(c);
                }
            }
        }
        return count == n;
    }
}
```

